18	/**
19	 * Null object perf optimization. Faster than `Object.create(null)` and `{ __proto__: null }`.
20	 */
21	const NullObject = /* @__PURE__ */ (() => {
22	  const C = function () {};
23	  C.prototype = Object.create(null);
24	  return C;
25	})() as unknown as { new (): any };
