27	export interface CreateOptions {
28	  /**
29	   * Content-Disposition type, defaults to "attachment"
30	   * @default "attachment"
31	   */
32	  type?: string;
33	  /**
34	   * Fallback filename for non-US-ASCII strings. If true, a fallback will be generated by replacing non-US-ASCII characters with "?". If false, no fallback will be generated.
35	   * @default true
36	   */
37	  fallback?: string | boolean;
38	}
