40	/**
41	 * Create an attachment Content-Disposition header.
42	 */
43	export function create(filename?: string, options?: CreateOptions): string {
44	  const type = options?.type || 'attachment';
45	  const parameters = createParameters(filename, options?.fallback);
46	
47	  return format({ type, parameters }, { extended: false });
48	}
