50	const SP = 32; // " "
51	const HTAB = 9; // "\t"
52	const SEMI = 59; // ";"
53	const EQ = 61; // "="
54	const DQUOTE = 34; // '"'
55	const BSLASH = 92; // "\\"
56	const ASTERISK = 42; // "*"
57	
58	export interface ParseOptions {
59	  /**
60	   * Whether to decode RFC 8187 encoded parameters.
61	   * @default true
62	   */
63	  extended?: boolean;
64	  /**
65	   * Parse parameters as sent by browsers in `multipart/form-data`.
66	   * @default false
67	   */
68	  multipart?: boolean;
69	}
70	
71	/**
72	 * Parse Content-Disposition header string.
73	 */
74	export function parse(
75	  header: string,
76	  options?: ParseOptions,
77	): ContentDisposition {
78	  const len = header.length;
79	  const multipart = options?.multipart === true;
80	  const extended = options?.extended !== false;
81	  let index = skipOWS(header, 0, header.length);
82	
83	  const typeStart = index;
84	  index = parseToken(header, index, len);
85	  const typeEnd = trailingOWS(header, typeStart, index);
86	  const type = header.slice(typeStart, typeEnd).toLowerCase();
87	
88	  const parameters: Record<string, string> = new NullObject();
89	
90	  parameter: while (index < len) {
91	    index = skipOWS(header, index + 1, len); // Skip over semicolon.
92	
93	    const keyStart = index;
94	
95	    while (index < len) {
96	      const char = header.charCodeAt(index);
97	      if (char === SEMI) continue parameter;
98	
99	      if (char === EQ) {
100	        const keyEnd = trailingOWS(header, keyStart, index);
101	        const key = header.slice(keyStart, keyEnd).toLowerCase();
102	
103	        index = skipOWS(header, index + 1, len);
104	
105	        if (index < len && header.charCodeAt(index) === DQUOTE) {
106	          index++;
107	
108	          let value = '';
109	
110	          if (multipart) {
111	            while (index < len) {
112	              const code = header.charCodeAt(index++);
113	              if (code === DQUOTE) {
114	                index = parseToken(header, index, len);
115	                if (parameters[key] === undefined) parameters[key] = value;
116	                break;
117	              }
118	
119	              if (code === /* % */ 37 && index + 1 < len) {
120	                const code2 = header.charCodeAt(index);
121	                const code3 = header.charCodeAt(index + 1);
122	
123	                if (code2 === 50 /* "2" */ && code3 === 50 /* "2" */) {
124	                  value += '"';
125	                  index += 2;
126	                  continue;
127	                }
128	
129	                if (code2 === 48 /* "0" */) {
130	                  if (code3 === 100 /* "d" */ || code3 === 68 /* "D" */) {
131	                    value += '\r';
132	                    index += 2;
133	                    continue;
134	                  }
135	
136	                  if (code3 === 97 /* "a" */ || code3 === 65 /* "A" */) {
137	                    value += '\n';
138	                    index += 2;
139	                    continue;
140	                  }
141	                }
142	              }
