150	                index = parseToken(header, index, len);
151	                if (parameters[key] === undefined) parameters[key] = value;
152	                break;
153	              }
154	
155	              if (code === BSLASH && index < len) {
156	                value += header[index++];
157	                continue;
158	              }
159	
160	              value += String.fromCharCode(code);
161	            }
162	          }
163	
164	          continue parameter;
165	        }
166	
167	        const valueStart = index;
168	        index = parseToken(header, index, len);
169	        const valueEnd = trailingOWS(header, valueStart, index);
170	        const value = header.slice(valueStart, valueEnd);
171	
172	        if (parameters[key] === undefined) {
173	          parameters[key] = value;
174	
175	          if (extended && key.charCodeAt(key.length - 1) === ASTERISK) {
176	            const normalizedKey = key.slice(0, -1);
177	            const decoded = decodeExtended(value);
178	            if (decoded !== undefined) parameters[normalizedKey] = decoded;
179	          }
180	        }
181	
182	        continue parameter;
183	      }
184	
185	      index++;
186	    }
187	  }
188	
189	  return { type, parameters };
190	}
