192	/**
193	 * RegExp to match non attr-char, *after* encodeURIComponent (i.e. not including "%")
194	 */
195	const ENCODE_URL_ATTR_CHAR_REGEXP = /[\x00-\x20"'()*,/:;<=>?@[\\\]{}\x7f]/g; // eslint-disable-line no-control-regex
196	
197	/**
198	 * RegExp to match non-US-ASCII characters.
199	 */
200	const NON_ASCII_REGEXP = /[^\x20-\x7e]/g;
201	
202	/**
203	 * RegExp to match chars that must be quoted-pair in RFC 2616
204	 */
205	const QUOTE_REGEXP = /[\\"]/g;
206	
207	/**
208	 * Match chars that can't be used in the filename for compatibility.
209	 */
210	const INVALID_FILENAME_REGEXP = /%[0-9A-Fa-f]{2}/;
211	
212	/**
213	 * RegExp for various RFC 2616 grammar
214	 *
215	 * parameter     = token "=" ( token | quoted-string )
216	 * token         = 1*<any CHAR except CTLs or separators>
217	 * separators    = "(" | ")" | "<" | ">" | "@"
218	 *               | "," | ";" | ":" | "\" | <">
219	 *               | "/" | "[" | "]" | "?" | "="
220	 *               | "{" | "}" | SP | HT
221	 * quoted-string = ( <"> *(qdtext | quoted-pair ) <"> )
222	 * qdtext        = <any TEXT except <">>
223	 * quoted-pair   = "\" CHAR
224	 * CHAR          = <any US-ASCII character (octets 0 - 127)>
225	 * TEXT          = <any OCTET except CTLs, but including LWS>
226	 * LWS           = [CRLF] 1*( SP | HT )
227	 * CRLF          = CR LF
228	 * CR            = <US-ASCII CR, carriage return (13)>
229	 * LF            = <US-ASCII LF, linefeed (10)>
230	 * SP            = <US-ASCII SP, space (32)>
231	 * HT            = <US-ASCII HT, horizontal-tab (9)>
232	 * CTL           = <any US-ASCII control character (octets 0 - 31) and DEL (127)>
233	 * OCTET         = <any 8-bit sequence of data>
234	 */
235	const TEXT_REGEXP = /^[\x20-\x7e\x80-\xff]*$/;
236	const ASCII_TEXT_REGEXP = /^[\x20-\x7e]*$/;
237	const TOKEN_REGEXP = /^[!#$%&'*+.0-9A-Z^_`a-z|~-]+$/;
238	
239	/**
240	 * Create parameters object from filename and fallback.
241	 */
242	function createParameters(
243	  filename?: string,
244	  fallback: string | boolean = true,
245	): Record<string, string> | undefined {
246	  if (filename === undefined) return;
247	
248	  if (typeof fallback === 'string') {
249	    if (!ASCII_TEXT_REGEXP.test(fallback)) {
250	      throw new TypeError('Fallback must be valid US-ASCII: ' + fallback);
251	    }
252	
253	    if (fallback === filename) return { filename };
254	    return { filename: fallback, 'filename*': encodeExtended(filename) };
255	  }
256	
257	  // Use `filename` when possible, otherwise use `filename*`.
258	  if (
259	    ASCII_TEXT_REGEXP.test(filename) &&
260	    !INVALID_FILENAME_REGEXP.test(filename)
261	  ) {
262	    return { filename };
263	  }
264	
265	  if (fallback === false) {
266	    return { 'filename*': encodeExtended(filename) };
267	  }
268	
269	  return {
270	    filename: getAscii(filename),
271	    'filename*': encodeExtended(filename),
272	  };
273	}
274	
275	/**
276	 * Decode a RFC 8187 field value (gracefully).
277	 */
278	export function decodeExtended(str: string): string | undefined {
279	  const charsetEnd = str.indexOf("'");
280	  if (charsetEnd <= 0) {
281	    return undefined;
282	  }
283	
284	  const languageEnd = str.indexOf("'", charsetEnd + 1);
285	  if (languageEnd === -1) {
286	    return undefined;
287	  }
288	
289	  const charset = str.slice(0, charsetEnd).toLowerCase();
290	  const encoded = str.slice(languageEnd + 1);
291	
292	  switch (charset) {
293	    case 'iso-8859-1': {
294	      return decodeHexEscapes(encoded);
295	    }
296	    case 'utf-8':
297	    case 'utf8': {
298	      return tryDecodeURIComponent(encoded);
299	    }
300	  }
301	
302	  return undefined;
303	}
304	
305	/**
306	 * Decode URI component but return `undefined` on error.
307	 */
308	function tryDecodeURIComponent(str: string): string | undefined {
309	  try {
310	    return decodeURIComponent(str);
311	  } catch {
312	    return undefined;
313	  }
314	}
315	
316	/**
317	 * Parse a token starting at the provided index.
318	 */
319	function parseToken(str: string, index: number, len: number): number {
320	  while (index < len) {
321	    const char = str.charCodeAt(index);
322	    if (char === SEMI) break;
323	    index++;
324	  }
325	  return index;
326	}
327	
328	/**
329	 * Skip RFC 2616 linear whitespace (space / tab).
330	 */
331	function skipOWS(str: string, index: number, len: number): number {
332	  while (index < len) {
333	    const char = str.charCodeAt(index);
334	    if (char !== SP && char !== HTAB) break;
335	    index++;
336	  }
337	  return index;
338	}
339	
340	/**
341	 * Skip RFC 2616 linear whitespace (space / tab) from the end of a string.
342	 */
343	function trailingOWS(str: string, start: number, end: number): number {
344	  while (end > start) {
345	    const char = str.charCodeAt(end - 1);
346	    if (char !== SP && char !== HTAB) break;
347	    end--;
348	  }
349	  return end;
350	}
351	
352	export interface FormatOptions {
353	  /**
354	   * Whether to use extended parameter encoding for non-ISO-8859-1 strings.
355	   * If false, an error will be thrown when formatting such strings.
356	   * @default true
357	   */
358	  extended?: boolean;
359	  /**
360	   * Format parameters as sent by browsers in `multipart/form-data`.
361	   * @default false
362	   */
363	  multipart?: boolean;
364	}
365	
366	/**
367	 * Format object to Content-Disposition header.
368	 */
369	export function format(
370	  obj: Partial<ContentDisposition>,
371	  options?: FormatOptions,
372	): string {
373	  const { type, parameters } = obj;
374	  const multipart = options?.multipart === true;
375	  const extended = options?.extended !== false;
376	
377	  if (!type || !TOKEN_REGEXP.test(type)) {
378	    throw new TypeError('Invalid type: ' + type);
379	  }
380	
381	  let result = type;
382	
383	  if (parameters) {
384	    for (const param of Object.keys(parameters)) {
385	      const value = parameters[param];
386	
387	      if (!TOKEN_REGEXP.test(param)) {
388	        throw new TypeError('Invalid parameter name: ' + param);
389	      }
390	
391	      if (multipart) {
392	        result += '; ' + param + '=' + qmultipart(value);
393	        continue;
394	      }
395	
396	      if (TOKEN_REGEXP.test(value)) {
397	        result += '; ' + param + '=' + value;
398	        continue;
399	      }
400	
401	      if (TEXT_REGEXP.test(value)) {
402	        result += '; ' + param + '=' + qstring(value);
403	        continue;
404	      }
405	
406	      if (!extended) {
407	        throw new TypeError('Invalid parameter value: ' + value);
408	      }
409	
410	      result += '; ' + param + '*=' + encodeExtended(value);
411	    }
412	  }
413	
414	  return result;
415	}
416	
417	/**
418	 * Get US-ASCII version of string.
419	 */
420	function getAscii(val: string): string {
421	  // simple Unicode -> US-ASCII transformation
422	  return val.replace(NON_ASCII_REGEXP, '?');
423	}
424	
425	/**
426	 * Percent encode a single character.
427	 */
428	function pencode(char: string): string {
429	  return '%' + char.charCodeAt(0).toString(16).toUpperCase();
430	}
431	
432	/**
433	 * Quote a string for HTTP.
434	 */
435	function qstring(str: string): string {
436	  return '"' + str.replace(QUOTE_REGEXP, '\\$&') + '"';
437	}
438	
439	/**
440	 * Quote a string for multipart/form-data.
441	 *
442	 * @see https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#multipart-form-data
443	 */
444	function qmultipart(str: string): string {
445	  return '"' + str.replace(/[\n\r"]/g, multipartEscape) + '"';
446	}
447	
448	/**
449	 * Escape a multipart/form-data string character.
450	 */
451	function multipartEscape(char: string): string {
452	  if (char === '\n') return '%0A';
453	  if (char === '\r') return '%0D';
454	  return '%22';
455	}
456	
457	/**
458	 * Encode a Unicode string for HTTP (RFC 8187).
459	 */
460	export function encodeExtended(str: string): string {
461	  const encoded = encodeURIComponent(str).replace(
462	    ENCODE_URL_ATTR_CHAR_REGEXP,
463	    pencode,
464	  );
465	
466	  return "UTF-8''" + encoded;
467	}
468	
469	/**
470	 * Check if a character is a hex digit [0-9A-Fa-f]
471	 */
472	function isHexDigit(char: string): boolean {
473	  const code = char.charCodeAt(0);
474	  return (
475	    (code >= 48 && code <= 57) || // 0-9
476	    (code >= 65 && code <= 70) || // A-F
477	    (code >= 97 && code <= 102) // a-f
478	  );
479	}
480	
481	/**
482	 * Decode hex escapes in a string (e.g., %20 -> space)
483	 */
484	function decodeHexEscapes(str: string): string | undefined {
485	  const firstEscape = str.indexOf('%');
486	  if (firstEscape === -1) return str;
487	
488	  let result = str.slice(0, firstEscape);
489	  for (let idx = firstEscape; idx < str.length; idx++) {
490	    if (str[idx] === '%') {
491	      // Reject malformed percent encoding, matches UTF-8 behavior.
492	      if (
493	        idx + 2 >= str.length ||
494	        !isHexDigit(str[idx + 2]) ||
495	        !isHexDigit(str[idx + 1])
496	      ) {
497	        return;
498	      }
499	
500	      result += String.fromCharCode(
501	        Number.parseInt(str[idx + 1] + str[idx + 2], 16),
502	      );
503	      idx += 2;
504	    } else {
505	      result += str[idx];
506	    }
507	  }
508	  return result;
509	}
